package com.erfansst.procmapdetector;import android.app.*;import android.os.*;import android.graphics.Color;import android.widget.*;public class MainActivity extends Activity{TextView out;static{System.loadLibrary("proc_detector");}public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,24,24,24);Button scan=new Button(this);scan.setText("SCAN /proc/<pid>/maps");out=new TextView(this);out.setTextSize(13);out.setTextColor(Color.WHITE);out.setBackgroundColor(Color.rgb(20,20,20));out.setPadding(16,16,16,16);ScrollView s=new ScrollView(this);s.addView(out);l.addView(scan);l.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(l);scan.setOnClickListener(v->runScan());runScan();}void runScan(){out.setText("Scanning...");new Thread(()->{String r=scan();runOnUiThread(()->out.setText(r));}).start();}public native String scan();}